begin;
select plan(40);
select ok(has_table_privilege('service_role','public.books_legal_entities','select'),'private server can read setup registry');
select ok(not has_table_privilege('anon','public.books_legal_entities','select'),'anonymous registry read denied');
select ok(not has_table_privilege('authenticated','public.books_legal_entities','select'),'organization login does not grant entity read');
select ok(not has_table_privilege('authenticated','public.books_legal_entity_members','insert'),'browser cannot grant entity access');
select ok(not has_table_privilege('authenticated','public.books_legal_entity_profiles','insert'),'browser cannot forge identity revisions');
select ok(not has_table_privilege('authenticated','public.books_legal_entity_profile_reviews','insert'),'browser cannot forge approval');
select ok(not has_table_privilege('authenticated','public.books_legal_entity_access_history','select'),'entity access audit is private');
select ok(not has_function_privilege('authenticated','public.create_books_legal_entity(uuid,uuid,text,uuid,text)','execute'),'creation requires private permission-checked service');
select ok(not has_function_privilege('authenticated','public.set_books_legal_entity_member(uuid,uuid,uuid,uuid,text,text)','execute'),'membership changes are private');
select ok(not has_function_privilege('authenticated','public.prepare_books_legal_entity_profile(uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute'),'identity preparation is private');
select ok(not has_function_privilege('authenticated','public.review_books_legal_entity_profile(uuid,uuid,uuid,uuid,text)','execute'),'identity approval is private');
select ok(not has_function_privilege('authenticated','public.read_books_legal_entity_setup(uuid,uuid,uuid,uuid,integer)','execute'),'entity reads are private');
select ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname in('books_entity_has_access','books_entity_member_guard','books_entity_member_audit','books_entity_profile_guard','books_entity_profile_review_guard','create_books_legal_entity','set_books_legal_entity_member','prepare_books_legal_entity_profile','review_books_legal_entity_profile','read_books_legal_entity_setup') and prosecdef),'entity functions never bypass RLS');
select is((select count(*)::integer from pg_class where oid in('public.books_legal_entities'::regclass,'public.books_legal_entity_members'::regclass,'public.books_legal_entity_access_history'::regclass,'public.books_legal_entity_profiles'::regclass,'public.books_legal_entity_profile_reviews'::regclass) and relrowsecurity),5,'all entity tables have RLS');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_legal_entity_profiles'::regclass and contype='f' and pg_get_constraintdef(oid) like '%org_id, legal_entity_id, previous_profile_id%'),'profile lineage is tenant and entity scoped');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_legal_entity_profile_reviews'::regclass and contype='f' and pg_get_constraintdef(oid) like '%org_id, legal_entity_id, profile_id%'),'approval is tenant and entity scoped');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_legal_entities'::regclass and contype='c' and pg_get_constraintdef(oid) like '%setup%'),'registry cannot activate an unenforced ledger');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_legal_entity_profiles'::regclass and contype='c' and pg_get_constraintdef(oid) like '%USD%'),'USD functional currency scope is enforced');
select ok(not has_function_privilege('authenticated','public.capture_books_entity_authorized_export(uuid,uuid)','execute'),'complete entity export is private');
select ok(has_function_privilege('service_role','public.capture_books_entity_authorized_export(uuid,uuid)','execute'),'permission-checked server can capture entity export');
select is((select data_type from information_schema.columns where table_schema='public' and table_name='books_legal_entity_access_history' and column_name='id'),'uuid','access events have stable archive row identities');
select is((select is_identity from information_schema.columns where table_schema='public' and table_name='books_legal_entity_access_history' and column_name='sequence_no'),'NO','audit ordering resumes from retained entity events without identity reseeding');
select ok(not has_table_privilege('authenticated','public.books_exports','select'),'browser cannot read private export manifest');
select ok(not has_table_privilege('authenticated','public.books_exports','update'),'browser cannot rewrite export proof');
select ok(not has_function_privilege('authenticated','public.assert_books_entity_export_download(uuid,uuid,uuid)','execute'),'download scope is checked by a private invoker RPC');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_legal_entity_profiles'::regclass and contype='f' and pg_get_constraintdef(oid) like '%prepared_access_event_id%'),'preparation pins same-entity access evidence');
select ok((select string_agg(pg_get_functiondef(oid),' ') from pg_proc where pronamespace='public'::regnamespace and proname like 'capture\_books\_export\_snapshot%') like '%t.id::text%', 'capture retains exact bigint audit identities before JSON transport');
select is((select count(*)::integer from pg_class where oid in('public.books_legacy_entity_proposals'::regclass,'public.books_legacy_entity_reviews'::regclass) and relrowsecurity),2,'legacy ownership history has RLS');
select ok(not has_table_privilege('authenticated','public.books_legacy_entity_proposals','select'),'legacy population is private');
select ok(not has_table_privilege('anon','public.books_legacy_entity_reviews','insert'),'anonymous cannot approve ownership');
select ok(not has_function_privilege('authenticated','public.prepare_books_legacy_entity_proposal(uuid,uuid,uuid,uuid,uuid,uuid,date,jsonb,text)','execute'),'legacy preparation is private');
select ok(not has_function_privilege('authenticated','public.review_books_legacy_entity_proposal(uuid,uuid,uuid,uuid,uuid,text)','execute'),'legacy review is private');
select ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname in('assert_books_legacy_entity_operation','capture_books_legacy_ownership_evidence','capture_books_legacy_ownership_population','books_legacy_entity_proposal_guard','books_legacy_entity_review_guard','prepare_books_legacy_entity_proposal','review_books_legacy_entity_proposal','read_books_legacy_entity_proposal') and prosecdef),'legacy review RPCs do not bypass RLS');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_legacy_entity_proposals'::regclass and contype='f' and pg_get_constraintdef(oid) like '%org_id, legal_entity_id, profile_id%'),'proposal identity is entity scoped');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_legacy_entity_proposals'::regclass and tgname='books_legacy_entity_proposals_immutable'),'prepared evidence cannot be rewritten');
select ok((select string_agg(pg_get_functiondef(oid),' ') from pg_proc where pronamespace='public'::regnamespace and proname like 'capture\_books\_export\_snapshot%') like '%books_legacy_entity_reviews%','schema19 captures retained ownership reviews');
select ok(not has_function_privilege('authenticated','public.list_books_legacy_entity_proposals(uuid,uuid,uuid,uuid,integer)','execute'),'ownership summaries require private authorization');
select ok(not has_function_privilege('authenticated','public.list_books_entity_review_options(uuid,uuid,uuid,text,text,uuid,integer)','execute'),'original evidence selection requires private authorization');
select ok(not has_function_privilege('authenticated','public.read_books_entity_setup_access(uuid,uuid,uuid)','execute'),'entity capabilities require private authorization');
select ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname in('list_books_legacy_entity_proposals','list_books_entity_review_options','read_books_entity_setup_access') and prosecdef),'workspace readers never bypass RLS');
select * from finish();
rollback;
